UPDATE t_system_config SET lifecycle_status='RETIRED',record_status='RETIRED',effective_to=NOW(3),
    record_version=record_version+1,change_reason=#{reason},is_active=0,updated_at=NOW(3)
    WHERE config_type='NER_ALLOWLIST'
    AND COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(config_value,'$.legacyId')) AS UNSIGNED),id)=#{id}
    AND record_status='ACTIVE' AND record_version=#{expectedVersion}
